{"res":"<style>
  {{resetCSS}}
  *{
      font-family: {{customFontName}}-apple-system, BlinkMacSystemFont, San Francisco, Segoe UI, Roboto, Helvetica Neue, sans-serif;;
      text-transform: initial !important;
      letter-spacing: initial !important;
  }
  .dk-flat-plugin {
    box-sizing: border-box;
    width: 100%;
    max-width: {{importedWidgetWidth}};
    padding: 15px;
    display: flex;
    border-radius: 2px;
    font-family: {{customFontName}}-apple-system, BlinkMacSystemFont, San Francisco, Segoe UI, Roboto, Helvetica Neue, sans-serif;
    flex-direction: column;
    {{if(options.showBorder)}}
    border: 1px solid {{fontColor}};
    {{#else}}
    border: none;
    {{/if}}
  }
  .title {
      padding-top: 10px;
      line-height: 1.5;
      font-weight: 400;
      font-family: {{customFontName}}-apple-system, BlinkMacSystemFont, San Francisco, Segoe UI, Roboto, Helvetica Neue, sans-serif;
      font-size: 12px;
  }

  .footer {
      display: flex;
      justify-content: space-between;
      align-items: flex-end;
      padding-top: 5px;
  }

  .learn-more {
      line-height: 1.5;
      font-size: 10px;
      font-weight: 500;
      text-decoration: none;
      font-family: {{customFontName}}-apple-system, BlinkMacSystemFont, San Francisco, Segoe UI, Roboto, Helvetica Neue, sans-serif;
      width: fit-content;
  }

  .learn-more:active {
      outline: 0;
  }

  .controls {
      display: flex;
      align-items: center;
      margin-top: 10px;
  }

  .control-btn, .control-input {
      {{if(options.hideOtherInput)}}
      width: 33%;
      height: 32px;
      {{#else}}
      width: 25%;
      height: 32px;
      {{/if}}
      /* {{if(!options.isTransparent)}}
      color: {{backgroundColor}};
      background: {{fontColor}};
      {{#else}}
      color: {{fontColor}};
      background: {{backgroundColor}};
      {{/if}} */
      color: {{fontColor}};
      background: {{backgroundColor}};
      margin-left: 4px;
      display: flex;
      justify-content: center;
      align-items: center;
      font-size: 12px;
      font-weight: 500;
      border-radius: 4px;
      {{if(options.buttonColor)}}
        background: {{buttonColor}};
      {{/if}}
  }

  .control-btn {
      cursor: pointer;
      user-select: none;
  }

  .control-input {
      -webkit-appearance: none !important;
      text-align:center;
      outline: none;
      border: none;
      {{if(options.hideOtherInput)}}
      display: none;
      {{/if}}
  }

  .control-input::placeholder {
      /* {{if(!options.isTransparent)}}
      color: {{backgroundColor}};
      {{#else}}
      color: {{fontColor}};
      {{/if}} */
      color: {{fontColor}};
      font-size: 12px;
      font-weight: 500;
      }
  .control-btn.active, .control-input.active, .control-input:focus {
      {{if(!options.isTransparent)}}
      background: {{fontColor}};
      color: {{backgroundColor}};
      {{#else}}
      background: {{backgroundColor}};
      color: {{fontColor}};
      {{/if}}
  }

  .control-btn:first-child {
      margin-left: 0;
  }

  .control-input {
      margin-left: 4px;
      height: 32px;
      padding: 0;
  }

  .created-by {
      line-height: 1.5;
      font-size: 8px;
      padding-top: 4px;
      display: flex;
      font-weight: 400;
      justify-content: center;
      align-items: center;
      padding-left: 15px;
      margin-right: -10px;
      font-family: {{customFontName}}-apple-system, BlinkMacSystemFont, San Francisco, Segoe UI, Roboto, Helvetica Neue, sans-serif;
  }

  .main-text {
      line-height: 1.4;
      font-weight: 700;
      font-size: 14px;
      font-family: {{customFontName}}-apple-system, BlinkMacSystemFont, San Francisco, Segoe UI, Roboto, Helvetica Neue, sans-serif;
  }

  .positioning {
      display: flex; width: 100%; min-height: 156px; justify-content: {{contentPosition}};
  }

  #powered-by-containter { justify-content: {{contentPosition}}; min-height: auto; }

  .powered-by {
    max-width: {{importedWidgetWidth}};
    margin-top: 10px;
    font-size: 9px;
    text-align: center;
    line-height: normal;
    font-family: {{customFontName}}-apple-system, BlinkMacSystemFont, San Francisco,  Segoe UI, Roboto, Helvetica Neue, sans-serif;
  }

  .powered-by a {
    line-height: initial !important;
  }


  {{if(options.isCenteredWidgetMobile)}}
  @media only screen and (max-width: 430px)  {
      .positioning {
          display: flex; width: 100%; justify-content: center;
      }
  #powered-by-containter { justify-content: center; }

  }
  {{/if}}

  .charity-logos {
    display: flex;
    justify-content: center;
    gap:10px;
  }

  .charity-logos .charity-logo-container {
    height: 60px;
    width: 60px;
    border-radius: 35px;
    box-shadow: 0px 4px 8px rgba(0, 0, 0, 0.1);
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 5px;
  }

  .charity-logos .charity-logo {
    height: 55px;
    width: 55px;
    border-radius: 50%;
  }

  .select-charities-link {
    color: {{linkColor}} !important;
    font-size: 12px;
    text-decoration: none !important;
    line-height: 12px;
    cursor: pointer;
    font-weight: 500;
  }

  .statistics {
    border-top: 1px solid #d8d8d8;
    border-bottom: 1px solid #d8d8d8;
    display: flex;
    padding-top: 10px;
    padding-bottom: 10px;
    font-size: 12px;
    margin-bottom:5px;
  }

  .statistics .contributors, .statistics .raised {
    text-align: center;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 50%;
    text-align: center;
  }
  .statistics .contributors {
    border-right: 1px solid #d8d8d8;
  }
  .statistics .value {
    font-weight: 700;
    font-size: 12px;
    margin-left:5px;
    margin-right: 5px;
  }

  #dk-flat-add {
    font-weight: 500;
    font-size: 12px;
  }

  #open-video-btn {
    display: inline-block;
    position: relative;
    width: 125px;
    height: 95px;
    cursor: pointer;
    margin-right: 10px;
    border-radius: 8px;
    background-color: {{buttonColor}};
    color: {{fontColor}};
    text-decoration: none;
  }

  #open-video-btn img {
    width: 100%;
    height: auto;
    min-height: 70%;
    border-top-left-radius: 8px;
    border-top-right-radius: 8px;
  }

  #open-video-btn .play-video {
    display: flex;
    position: absolute;
    top: 22%;
    left: 40%;
    width: 30px;
    height: 30px;
    background-color: #f4f4f4;
    border-radius: 50%;
    justify-content: center;
    align-items: center;
  }

  #open-video-btn figcaption {
    display: flex;
    align-items: center;
    justify-content: center;
    line-height: 5px;
    margin-top: 0px;
    font-size: 11px;
    font-weight: 700;
  }

  .video-container {
    position: fixed;
    top: 0;
    left: 0;
    z-index: 10000;
    width: 100vw;
    height: 100vh;
    display: flex;
    justify-content: center;
    align-items: center;
    visibility: hidden;
    opacity: 0;
  }

  .video-container #next-video-btn {
    margin-left: 20px;
    display: block;
    z-index: 999999;
    cursor: pointer;
  }

  .video-container #prev-video-btn {
    margin-right: 20px;
    display: block;
    z-index: 999999;
    cursor: pointer;
  }

  .video-container.active {
    visibility: visible;
    opacity: 1;
  }

  .video-container video {
    position: relative;
    border-radius: 4px;
    max-width: 900px;
    outline: none;
    border-radius: 16px;
  }

  .video-container svg {
    transform: scale(1.5);
    pointer-events: none;
  }

  .video-container .video-block {
    display: flex;
    justify-content: center;
    align-items: center;
  }

  #close-video-popup {
    display: flex;
    cursor: pointer;
    width: 24px;
    height: 24px;
    font-size: 22px;
    border-radius: 50%;
    align-self: flex-start;
    margin-top:5px;
    margin-left: -45px;
    z-index: 9999;
    padding: 5px;
  }

  @media(max-width: 991px) {
    .video-container video {
      position: relative;
      max-width: 70%;
      outline: none;
    }
  }

  .title-block {
    display: flex;
    align-items: center;
  }

  #dk-flat-plugin-widget-hidden {
    min-height: 125px;
    justify-content: center;
  }

  #dk-flat-plugin-widget-hidden .title {
    line-height: 1;
  }

  #dk-flat-plugin-widget-hidden .created-by {
    margin-left: 0;
  }
</style>
<div class="positioning">
